/*
 * A043995  Numbers k such that 7 and 8 occur juxtaposed in the base-9
 *          representation of k but not of k+1.
 * https://oeis.org/A043995
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the nth integer k such that 7 and 8 occur juxtaposed
 *            (either 78 or 87) in the base‑9 representation of k but not in
 *            the base‑9 representation of k+1. The sequence is generated by
 *            scanning successive integers and selecting those meeting the
 *            condition
 * Range:     u8 n <= 6, u16 n <= 42, u32 n <= 42, u64 n <= 42, u128 n <= 42,
 *            big any n
 * Validated: partial, pass, 42 terms through n = 42 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include "../utils/mem.h"

static bool has_adjacent_78_87(seq_t x)
{
    seq_t t = x;
    /* Scan from least significant digit upwards.
       For each position check the last two base‑9 digits. */
    while (t >= (seq_t)9) {
        seq_t lb = t % (seq_t)81;        /* two least significant base‑9 digits */
        if (lb == (seq_t)71 || lb == (seq_t)79) /* 71 = 78₉ , 79 = 87₉ */
            return true;
        t /= (seq_t)9;
    }
    return false;
}

static seq_t *cache = NULL;         /* cached terms */
static idx_t   cache_len = 0;       /* number of terms stored */
static idx_t   cache_cap = 0;       /* allocated capacity */
static seq_t   next_candidate = (seq_t)71; /* first candidate to test */

/* ensures that we have a writable buffer of at least 'need' elements */
static void ensure_cache_capacity(idx_t need)
{
    if (need <= cache_cap)
        return;
    idx_t new_cap = cache_cap ? cache_cap * 2 : 64;
    while (new_cap < need)
        new_cap *= 2;
    seq_t *new_buf = mem_resize(seq_t, cache, new_cap);
    cache = new_buf;
    cache_cap = new_cap;
}

seq_t a(idx_t n)
{
    /* Build cache up to index n (1‑based). */
    if (n == 0)
        return (seq_t)0; /* undefined for offset 1, but return 0 safely */

    if (n <= cache_len)
        return cache[n - 1];

    ensure_cache_capacity(n);

    while (cache_len < n) {
        /* Find next qualifying number. */
        while (true) {
            if (has_adjacent_78_87(next_candidate) &&
                !has_adjacent_78_87(next_candidate + (seq_t)1)) {
                break; /* found match */
            }
            ++next_candidate;
        }
        cache[cache_len++] = next_candidate;
        ++next_candidate; /* start next search after current value */
    }
    return cache[n - 1];
}
